(window.CRAM_PERSONAL=window.CRAM_PERSONAL||{})["clinical-pathophysiology-i-exam-1"]={"title":"Clinical Pathophysiology I Exam 1","sections":[{"id":"basics","title":"Definitions & Mechanisms","style":"--acc:#3b2a5e;--acc-bg:#e4e1e8;--acc-zebra:#f1f0f4;--acc-ink:#2e2149"},{"id":"acute-chronic","title":"Acute vs Chronic","style":"--acc:#6a4fa3;--acc-bg:#eae6f2;--acc-zebra:#f5f3f9;--acc-ink:#533e7f"},{"id":"patterns","title":"Patterns (8)","style":"--acc:#8f5aa8;--acc-bg:#efe8f3;--acc-zebra:#f7f3f9;--acc-ink:#704683"},{"id":"wbc","title":"White Blood Cells","style":"--acc:#4a6fb5;--acc-bg:#e6ebf5;--acc-zebra:#f2f5fa;--acc-ink:#3a578d"},{"id":"sequence","title":"Sequence of Acute Inflammation","style":"--acc:#2f7d76;--acc-bg:#e2edec;--acc-zebra:#f0f6f5;--acc-ink:#25625c"},{"id":"mediators","title":"Mediators & Opsonins","style":"--acc:#a4502a;--acc-bg:#f2e6e1;--acc-zebra:#f9f3f0;--acc-ink:#803e21"},{"id":"derm-anatomy","title":"Integument — Anatomy","style":"--acc:#7a4a8f;--acc-bg:#ece6ef;--acc-zebra:#f6f2f7;--acc-ink:#5f3a70"},{"id":"derm-primary","title":"Primary Lesions","style":"--acc:#5a4fa3;--acc-bg:#e8e6f2;--acc-zebra:#f3f3f9;--acc-ink:#463e7f"},{"id":"derm-secondary","title":"Secondary Lesions & Healing","style":"--acc:#2f6f8f;--acc-bg:#e2ebef;--acc-zebra:#f0f5f7;--acc-ink:#255770"},{"id":"derm-mech","title":"Mechanisms of Common Conditions","style":"--acc:#8a5a2b;--acc-bg:#efe8e1;--acc-zebra:#f7f3f0;--acc-ink:#6c4622"},{"id":"derm-cancer","title":"Skin Cancers & Nails","style":"--acc:#a03a55;--acc-bg:#f2e3e7;--acc-zebra:#f8f1f3;--acc-ink:#7d2d42"},{"id":"acg-nonneo","title":"Non-Neoplastic Abnormalities of Growth","style":"--acc:#4a5f8a;--acc-bg:#e3e8f1;--acc-zebra:#f1f4f8;--acc-ink:#3a4b6e"},{"id":"acg-neoplasia","title":"Neoplasia, Grading & Benign vs Malignant","style":"--acc:#8f3f5c;--acc-bg:#f3e3ea;--acc-zebra:#f9f1f4;--acc-ink:#702e46"},{"id":"acg-spread-class","title":"Routes of Spread & Classification by Origin","style":"--acc:#3f6b5a;--acc-bg:#e2ede8;--acc-zebra:#f1f6f4;--acc-ink:#2f5344"},{"id":"acg-carcinogenesis","title":"Gene Alterations, Chemicals, Microbes & Heredity","style":"--acc:#8a4a2c;--acc-bg:#f4e7e0;--acc-zebra:#faf3ef;--acc-ink:#6d3921"},{"id":"acg-staging","title":"Cancer Staging & TNM","style":"--acc:#5d6f2f;--acc-bg:#eaefdf;--acc-zebra:#f4f7ee;--acc-ink:#48561f"},{"id":"acg-lecture","title":"From the Abnormal Cell Growth Lecture Recording","style":"--acc:#8a3f4a;--acc-bg:#f3e3e6;--acc-zebra:#faf1f3;--acc-ink:#6d2f38"},{"id":"l4-exam-list","title":"★ KNOW FOR EXAM — HE STATED THESE","style":"--acc:#b8860b;--acc-bg:#f7efd9;--acc-zebra:#fbf7ec;--acc-ink:#7a5a08"},{"id":"l4-anatomy","title":"Eye Anatomy & Vision Physiology","style":"--acc:#3b2a5e;--acc-bg:#e4e1e8;--acc-zebra:#f1f0f4;--acc-ink:#2e2149"},{"id":"l4-refract","title":"Globe Shape & Age-Related","style":"--acc:#6a4fa3;--acc-bg:#eae6f2;--acc-zebra:#f5f3f9;--acc-ink:#533e7f"},{"id":"l4-cat-glauc","title":"Cataract & Glaucoma","style":"--acc:#8f5aa8;--acc-bg:#efe8f3;--acc-zebra:#f7f3f9;--acc-ink:#704683"},{"id":"l4-retina","title":"Retina, Macula & Diabetic Cascade","style":"--acc:#2f7d76;--acc-bg:#e2edec;--acc-zebra:#f0f6f5;--acc-ink:#25625c"},{"id":"l4-fields","title":"Visual Field Deficits by Lesion Site","style":"--acc:#a4502a;--acc-bg:#f2e6e1;--acc-zebra:#f9f3f0;--acc-ink:#803e21"}],"rows":[{"t":"Term","d":"What you need to know","s":0},{"t":"Inflammation","d":"The reaction of VASCULARIZED living tissue to injury. Avascular tissue cannot mount one.","s":0},{"t":"Two healing routes","d":"New tissue from native parenchymal cells, OR fibroblastic scar tissue.","s":0},{"t":"Five main processes","d":"Increased blood flow → increased permeability → migration of neutrophils → chemotaxis → leucocyte recruitment and activation.","s":0},{"t":"The vascular causal chain","d":"Vasodilation of arterioles (more flow) → endothelial contraction (more permeability) → exudation (fluid + blood proteins into interstitium). Each step enables the next.","s":0},{"t":"Term","d":"What you need to know","s":1},{"t":"Acute","d":"Seconds/minutes/hours/days. Begins WITHIN SECONDS of injury. Damage may be purely physical or involve immune activation (trauma vs bee sting).","s":1},{"t":"Chronic","d":"Days/weeks/months. Histology: lymphocytes and macrophages, proliferation of blood vessels, fibrosis, tissue necrosis.","s":1},{"t":"3 causes of chronic","d":"Persistent infection · prolonged toxic agents · autoimmunity.","s":1},{"t":"Toxic agents","d":"ENDOgenous = atherosclerosis. EXOgenous = particulates such as silica.","s":1},{"t":"Autoimmune examples","d":"Rheumatoid arthritis, lupus.","s":1},{"t":"Chronic cell roles","d":"Lymphocytes + plasma cells mediate ANTIBODY production. Macrophages PROCESS and DELIVER antigen to immunocompetent cells.","s":1},{"t":"Term","d":"What you need to know","s":2},{"t":"Serous","d":"Largely plasma, LOW protein. Early or mild.","s":2},{"t":"Fibrinous","d":"Lots of fibrinogen → thick meshwork. Removable ONLY by fibrolytic enzymes; failure → scar tissue.","s":2},{"t":"Suppurative / purulent","d":"Remnants of WBCs, protein, tissue debris = pus.","s":2},{"t":"Hemorrhagic","d":"Damage to blood vessels; occurs WITH other exudates.","s":2},{"t":"Catarrhal","d":"Mucus hypersecretion on a mucous membrane.","s":2},{"t":"Ulcerative","d":"Necrosis + sloughing of surface epithelium → EXPOSES connective tissue beneath (removes a layer).","s":2},{"t":"Pseudomembranous","d":"Superficial necrotic layer of fibrin/inflammatory cells/debris → membrane-like covering OVER mucosa (adds a layer).","s":2},{"t":"Gangrenous","d":"Severe necrosis ± bacterial infection. DRY = coagulative. WET = liquefactive, from infection.","s":2},{"t":"Term","d":"What you need to know","s":3},{"t":"Granulocytes (PMN)","d":"Neutrophils, basophils, eosinophils. Granules = membrane-bound enzymes digesting phagocytized particles. PMN = ALL granulocytes, not just neutrophils.","s":3},{"t":"Agranulocytes","d":"Lymphocytes (B, T), monocytes, macrophages. Do contain non-specific azurophilic granules (lysosomes) despite the name.","s":3},{"t":"Neutrophil","d":"First responder to microbial infection; bacterial + fungal. Multilobed nucleus, fine pale lilac granules. CANNOT renew lysosomes → dies after a few pathogens → forms pus.","s":3},{"t":"Basophil","d":"Bi-/tri-lobed nucleus, coarse granules. Allergic and antigen response via HISTAMINE.","s":3},{"t":"Eosinophil","d":"Bi-lobed nucleus, PINK-ORANGE granules. Parasites; predominant cell in allergy (asthma, hay fever, hives).","s":3},{"t":"B lymphocyte","d":"Humoral. Makes antibody, acts as antigen-presenting cell, becomes memory B cell.","s":3},{"t":"T lymphocyte","d":"Matures in Thymus; carries T cell receptors. Helper = activate/regulate T and B. CD8+ cytotoxic and NK = virus-infected and tumour cells. Regulatory = restore normal function, prevent autoimmunity.","s":3},{"t":"Monocyte","d":"Kidney-shaped nucleus, abundant agranulated cytoplasm. Phagocytoses then presents to T cells; becomes tissue macrophage. CAN replace lysosomal contents.","s":3},{"t":"Term","d":"What you need to know","s":4},{"t":"Vascular (1–4)","d":"Vasoconstriction → vasodilation → increased vascular permeability → haemoconcentration and stasis.","s":4},{"t":"Cellular (5–9)","d":"Leukocyte adhesion → transmigration → chemotaxis → aggregation → phagocytosis.","s":4},{"t":"Why stasis matters","d":"Slowed flow is the hinge — it lets leukocytes reach and hold against the endothelium, so adhesion can begin.","s":4},{"t":"Digestion of foreign material","d":"Recognition → attachment → engulfment → degradation. Recognition and attachment are enhanced by opsonins.","s":4},{"t":"Acute in review","d":"Short term (minutes–days). Exudation of fluid, plasma, proteins, leukocytes (neutrophils); phagocytosis and enzymatic release.","s":4},{"t":"Term","d":"What you need to know","s":5},{"t":"Histamine","d":"FIRST mediator of the initial response. Dilates arterioles; increases permeability of capillaries and venules.","s":5},{"t":"Serotonin","d":"Vasodilation and increased vascular permeability.","s":5},{"t":"Bradykinin","d":"Increases capillary permeability, CAUSES PAIN, may increase leukocyte chemotaxis. Pain is the discriminator.","s":5},{"t":"Complement","d":"10% of circulating serum proteins. Chemotactic to neutrophils and monocytes; cascade may damage bacteria.","s":5},{"t":"Coagulation system","d":"Fibrous network traps exudate, microorganisms, foreign bodies; stops bleeding so repair can begin.","s":5},{"t":"Opsonin","d":"Protein adhering to foreign material, making it easier for immune cells to recognise and attach.","s":5},{"t":"IgG vs C3b","d":"IgG = antibody, read by Fc RECEPTORS on macrophages/neutrophils. C3b = complement fragment, read by COMPLEMENT RECEPTORS.","s":5},{"t":"Biomaterial pearl","d":"Anything not human put into a human gets coated with IgG and C3b → immune cells attach. An implanted device can inflame even when STERILE.","s":5},{"t":"Three layers","d":"Epidermis · dermis · subcutaneous (hypodermis). Nerves and vasculature sit in the DERMIS — the epidermis has no blood supply of its own.","s":6},{"t":"Epidermal cell types","d":"Keratinocytes (~90%), melanocytes, Merkel cells, Langerhans cells. Turnover every 30–60 days, faster in younger patients.","s":6},{"t":"Strata, deep → superficial","d":"Basale (the only dividing layer) · spinosum (desmosomes = prickle cells; Langerhans) · granulosum (keratohyalin) · lucidum · corneum (20–30 dead layers = the barrier).","s":6},{"t":"Dermis","d":"Papillary (thin, superficial) and reticular (dense, deep). Collagen from fibroblasts = tensile strength; elastin + fibrillin = recoil. Mast cells mediate immunoglobulin E inflammation.","s":6},{"t":"Vitamin D chain","d":"Cholecalciferol made in SKIN under ultraviolet B → hydroxylated in LIVER → then KIDNEY → calcitriol. Three organs.","s":6},{"t":"Sweat glands","d":"Eccrine: onto the surface, water and electrolytes, cooling. Apocrine: axilla/anogenital, protein and lipids, scent — odour comes from bacterial degradation.","s":6},{"t":"Hair","d":"Terminal (thick, androgen-regulated) · lanugo (newborn) · vellus (fine, androgen-independent).","s":6},{"t":"NOT palpable","d":"Macule (≤5 mm) and patch (>5 mm). Hyperpigmented = more melanin in basal layer; hypopigmented = LOSS of melanocytes (vitiligo).","s":7},{"t":"Palpable and solid","d":"Papule (<5 mm, epidermal hyperplasia + hyperkeratosis) · nodule (>5 mm, dermal, dense collagen) · plaque (>1 cm, confluence of papules).","s":7},{"t":"Vesicle vs bulla","d":"Vesicle ≤5 mm, fluid within or just beneath epidermis. Bulla >5 mm, SEPARATION of epidermis from dermis — a deeper plane, not just bigger.","s":7},{"t":"Wheal","d":"Mast cell histamine → vasodilation + permeability → plasma into dermis; histamine also hits nerve endings → pruritus. Transient.","s":7},{"t":"Pustule","d":"Purulent: leukocytes, debris, serous fluid, ± organisms. Usually Staphylococcus aureus or Streptococcus pyogenes — but MAY BE STERILE (rosacea).","s":7},{"t":"Cyst vs tumor","d":"Epidermal inclusion cyst: from a hair follicle, keratin-filled. Tumor >2 cm, rapid growth, benign or malignant. Dermatofibroma = fibrous; lipoma = adipocytes.","s":7},{"t":"Scale vs crust","d":"Scale = desquamating stratum corneum (psoriasis). Crust = dried sebum, debris, blood or necrotic skin (impetigo).","s":8},{"t":"Lichenification","d":"Itch-scratch cycle → hyperplasia and hyperkeratosis. Thick plaques WITHOUT scaling (lichen simplex chronicus).","s":8},{"t":"Erosion vs ulcer","d":"Erosion stays ABOVE the dermal-epidermal junction. Ulcer crosses it into dermis, destroying collagen — which is why an ulcer scars and an erosion does not.","s":8},{"t":"Fissure","d":"Linear ulcer, a crack, from lost elasticity, dryness and mechanical tension, with hyperkeratosis.","s":8},{"t":"Atrophy","d":"Keratinocyte division slows + collagen synthesis slows + elastin degrades.","s":8},{"t":"Healing, 3 phases","d":"Inflammatory d1–3 (fibrin plug, neutrophils/macrophages, growth factors) · Proliferative d4–21 (granulation = macrophages + fibroblasts + endothelial cells) · Remodelling d21–1 yr.","s":8},{"t":"Remodelling","d":"Type III collagen replaced by stronger type I, in small PARALLEL bundles — normal dermis is BASKET-WEAVE. That difference is why a scar never matches.","s":8},{"t":"Keloid","d":"Fibroblast dysregulation prolongs the proliferative phase + deposition/degradation imbalance in remodelling → haphazard bundles that EXCEED the original wound boundary.","s":8},{"t":"Petechiae / purpura / ecchymoses","d":"One process at three sizes: ≤1–2 mm / 3–10 mm / >10 mm. Bleeding into dermis, non-blanchable. Henoch-Schonlein = immunoglobulin A vasculitis, skin/joints/kidneys/intestines, ages 3–10.","s":9},{"t":"Telangiectasia","d":"Permanent dilatation and endothelial thinning of superficial dermal vessels — NO inflammatory infiltrate. That absence is the discriminator.","s":9},{"t":"Urticaria","d":"Mast cell degranulation → histamine → wheals.","s":9},{"t":"Allergic vs irritant contact","d":"Allergic = delayed hypersensitivity 48–72 h; sensitization (Langerhans present haptens to T cells) then elicitation. Irritant = direct chemical injury, NO prior exposure needed.","s":9},{"t":"Eczema","d":"T cell-mediated + insufficient FILAGGRIN (barrier defect). “The itch that rashes.”","s":9},{"t":"Psoriasis","d":"Autoimmune; cells multiply up to 10× faster. T cells → keratinocyte proliferation + tumour necrosis factor alpha, interferon gamma, interleukin-12. Epidermal hyperplasia, LOSS OF STRATUM GRANULOSUM, no lipid secretion (xeroderma).","s":9},{"t":"Seborrhoeic keratosis vs actinic keratosis","d":"SK = BENIGN immature keratinocyte proliferation, ?fibroblast growth factor receptor-3. AK = ultraviolet damage → DYSPLASTIC keratinocytes; most common precancer, risk of squamous cell carcinoma.","s":9},{"t":"Verrucae","d":"Human papillomavirus enters epidermal BASAL cells through microabrasions → epidermal proliferation.","s":9},{"t":"Dermatophytes","d":"Trichophyton, Microsporum, Epidermophyton. Keratinases and proteases digest keratin in the STRATUM CORNEUM → annular patch with central clearing.","s":9},{"t":"Basal cell carcinoma","d":"Most common skin cancer AND most common malignancy in humans. Ultraviolet mutation of basal keratinocytes → HEDGEHOG pathway overactivation. Head/neck, slow, rarely metastasises.","s":10},{"t":"Squamous cell carcinoma","d":"Second most common. Ultraviolet DNA damage + tp53 mutation, from keratinocytes. KERATIN PEARLS are pathognomonic. Immunosuppression is a notable risk.","s":10},{"t":"Melanoma","d":"From melanocytes at the dermal-epidermal junction. Ultraviolet + oxidative stress. Risk inherited autosomal dominant with variable penetrance.","s":10},{"t":"Melanoma growth order","d":"Radial (within epidermis) → vertical (into dermis) → thickness → metastatic. The radial-to-vertical shift is when depth starts to matter.","s":10},{"t":"Nails","d":"Leukonychia = incomplete keratinization (± heavy metals) · koilonychia = impaired keratin synthesis, deficiency anaemia · Beau's lines = HALT of keratin production · Terry's = connective tissue overgrowth · clubbing = increased capillary density via vascular endothelial growth factor.","s":10},{"t":"Sort the seven into three groups","d":"FAILED TO DEVELOP: agenesis, aplasia, hypoplasia. CHANGED SIZE: atrophy, hypertrophy. CHANGED KIND: metaplasia, dysplasia.","s":11},{"t":"Agenesis vs aplasia","d":"AGENESIS = complete absence, the PRIMORDIAL TISSUE NEVER FORMED. APLASIA = the primordial tissue EXISTS but fails to develop into the mature organ. A timing question.","s":11},{"t":"Hypoplasia vs atrophy","d":"HYPOPLASIA = PARTIAL development, resulting in a FUNCTIONAL DEFICIENCY — it never got there. ATROPHY = shrinkage of a tissue or organ THAT HAD FORMED AND MATURED NORMALLY — it got there and shrank back.","s":11},{"t":"Hypertrophy","d":"Enlargement due to enlargement of INDIVIDUAL CELLS. Especially important in PERMANENT TISSUES — skeletal and cardiac muscle — but may occur elsewhere as adaptive growth. Contrast hyperplasia: MORE cells, not BIGGER cells.","s":11},{"t":"Metaplasia","d":"Change of ONE CELL TYPE TO ANOTHER in response to a CHRONICALLY IRRITATING OR INJURIOUS stimulus; involves a change in DIFFERENTIATION. The slide&#x27;s example: bladder TRANSITIONAL epithelium → SQUAMOUS. Still orderly, still mature, NOT precancerous.","s":11},{"t":"Dysplasia — four features","d":"DISORDERED GROWTH, typically EPITHELIAL. (1) variation in cellular SIZE AND SHAPE, (2) LOSS OF ARCHITECTURAL ORIENTATION, (3) nuclei may be DARKER AND LARGER, (4) MAY PROGRESS TO CANCER — PRECANCEROUS.","s":11},{"t":"The line that matters","d":"Normal → mild → moderate → severe dysplasia → CARCINOMA IN SITU → INVASIVE CANCER. The BASEMENT MEMBRANE stays intact until the last panel. Everything up to and including carcinoma in situ is still above it — which is exactly what Tis means.","s":11},{"t":"Neoplasm — the defining word","d":"An abnormal mass growing AUTONOMOUSLY — self-perpetuating WITHOUT PHYSIOLOGIC GROWTH STIMULI. That is what separates it from hyperplasia, which stops when the stimulus stops. Interchangeable with TUMOR.","s":12},{"t":"Clonal origin","d":"The ENTIRE proliferating population is derived from ONE CELL that underwent a genetic alteration.","s":12},{"t":"Two components","d":"PARENCHYMA = the proliferating neoplastic cells. STROMA = connective tissue and blood vessels. The stroma is host tissue, not part of the clone.","s":12},{"t":"Cancer &amp; metastasis","d":"CANCER = a MALIGNANT neoplasm. From the Latin for CRAB — &#x27;adheres to any tissue it seizes upon&#x27;, reaches out with claws. METASTASIS = the portion that has MIGRATED from the primary site.","s":12},{"t":"Histological GRADING (objective k)","d":"Measures how closely the neoplasm RESEMBLES comparable normal cells in appearance and function. WELL differentiated (close) → MODERATELY → POORLY → ANAPLASIA (LACK of differentiation).","s":12},{"t":"GRADING vs STAGING","d":"GRADING asks WHAT DOES IT LOOK LIKE. STAGING asks HOW FAR HAS IT GOT. Different questions, both still used.","s":12},{"t":"Benign vs malignant","d":"BENIGN: well circumscribed border · COMPRESSES surrounding tissue · often a FIBROUS CAPSULE · usually WELL differentiated · does NOT metastasize · SLOW growing. MALIGNANT: RAGGED border · INFILTRATES AND INVADES · VARIOUS degrees of differentiation · MAY metastasize · grows RAPIDLY.","s":12},{"t":"Four histological features of malignancy","d":"PLEOMORPHISM · ABNORMAL NUCLEI · MITOSES · ABNORMAL DIFFERENTIATION.","s":12},{"t":"Stem cell kinetics — why tumours outgrow tissue","d":"A stem cell has UNLIMITED SELF-RENEWAL and CELLULAR IMMORTALITY but a RELATIVELY LOW rate of proliferation; committed progeny proliferate dramatically but have a LIMITED LIFE-SPAN. In cancer, abnormal differentiation puts MORE cells in the PROLIFERATIVE pool at the expense of the MATURATION pool. Growth exceeds normal via a HIGHER PROLIFERATIVE FRACTION AND A LOWER RATE OF CELL LOSS — both halves.","s":12},{"t":"Haematogenous spread","d":"Typically through VEINS — especially the PORTAL VEIN and INFERIOR VENA CAVA, so cancers often spread to LIVER and LUNGS respectively. Mechanism: cells SEPARATE from each other and DEGRADE INTERCELLULAR TISSUE WITH ENZYMES → invade the vessel → MULTIPLE fragments travel. One organ may carry several nodules.","s":13},{"t":"Lymphatic spread","d":"Cancer spreads into lymphatic vessels AT THE TUMOUR MARGIN and follows the NATURAL ROUTE OF LYMPHATIC DRAINAGE. That predictability is what makes nodal staging meaningful.","s":13},{"t":"Seeding","d":"Invasion of tumour THROUGH AN ORGAN SURFACE into a cavity. PERICARDIAL, PLEURAL, PERITONEAL cavities; JOINT cavities; SUBARACHNOID space. MOST COMMONLY THE PERITONEAL CAVITY. A cavity is defined by the membrane covering the organs plus the membrane covering the cavity wall.","s":13},{"t":"Metastasis is NOT random","d":"Determined by: PATTERN OF VENOUS BLOOD FLOW · SPECIFIC RECEPTORS on tumour and endothelial cells · METASTATIC &#x27;FITNESS&#x27; IS GENETICALLY DETERMINED.","s":13},{"t":"The three hurdles after invasion","d":"PENETRATION OF VASCULATURE → SURVIVAL IN CIRCULATION → SURVIVAL IN A NEW ORGAN. Reaching the bloodstream is only the first.","s":13},{"t":"THE NAMING RULE","d":"MESENCHYMAL (supportive tissue: connective tissue, adipose, cartilage, smooth and striated muscle, bone) → malignant = SARCOMA. EPITHELIAL → malignant = CARCINOMA.","s":13},{"t":"Benign epithelial names","d":"ADENOMA = benign epithelial tumour with a GLANDULAR pattern or from a gland; sometimes SECRETES the hormone of its gland of origin. PAPILLOMA = visible FINGER-LIKE or WARTY projections from an epithelial surface.","s":13},{"t":"Malignant epithelial names","d":"CARCINOMA. With glandular growth pattern = ADENOCARCINOMA. With squamous cell differentiation = SQUAMOUS CELL CARCINOMA.","s":13},{"t":"Carcinogenesis in one line","d":"A MULTISTEP process resulting from damage to MULTIPLE normal regulatory genes. Damage may be INHERITED and/or from CHEMICAL CARCINOGENS, ULTRAVIOLET AND IONIZING RADIATION, or MICROBIAL ORGANISMS (viruses and a bacterium).","s":14},{"t":"FOUR categories of gene alteration","d":"(1) PROTOONCOGENES — promote REGULATED growth (growth factors, their receptors, nuclear regulatory proteins, signal transduction proteins); mutation → ONCOGENES → ONCOPROTEINS → UNCONTROLLED growth. (2) TUMOUR SUPPRESSOR GENES — INHIBIT growth; NF-1, NF-2, RB, APC. (3) DNA REPAIR GENES — BRCA-1, BRCA-2. (4) APOPTOSIS GENES — make damaged cells self destruct, PREVENTING damage becoming permanent in dividing cells.","s":14},{"t":"Chemical carcinogenesis — two steps","d":"INITIATION (initiators): chemicals cause PERMANENT DAMAGE TO DNA. PROMOTION (promoters): SUSTAINED OR ENHANCED PROLIFERATION of cells ALREADY DAMAGED, increasing the risk of successive mutations.","s":14},{"t":"The two named chemicals","d":"POLYCYCLIC AROMATIC HYDROCARBONS — from COMBUSTION OF TOBACCO — bladder and lung cancer; among the MOST POWERFUL CARCINOGENS KNOWN. AROMATIC AMINES — classically emphasised in OCCUPATIONAL BLADDER CANCER.","s":14},{"t":"HPV","d":"Types 16 AND 18 cause most CERVICAL cancer. INTEGRATES viral DNA into the host genome → excess E6 and E7. E6 BLOCKS p53 (needed for self destruction of mutated cells); E7 BLOCKS RB (needed to inhibit cell growth). Also anal, vulvar, vaginal, penile, and OROPHARYNGEAL squamous cell carcinoma.","s":14},{"t":"Epstein Barr virus","d":"Certain B CELL LYMPHOMAS and NASOPHARYNGEAL CARCINOMA. Infects B lymphocytes and IMMORTALIZES them; also infects oropharyngeal epithelium. With NORMAL IMMUNE FUNCTION there is no immortalization → asymptomatic or SELF-LIMITED INFECTIOUS MONONUCLEOSIS.","s":14},{"t":"Hepatitis B","d":"HEPATOCELLULAR CARCINOMA. Chronic infection and injury → CONTINUOUS REGENERATIVE ATTEMPTS → cells at risk of mutation. ALSO encodes a protein that BINDS p53. Emphasises: CHRONIC INFLAMMATION · REGENERATIVE HYPERPLASIA · GENOMIC INSTABILITY.","s":14},{"t":"Hepatitis C","d":"HEPATOCELLULAR CARCINOMA via chronic hepatitis → repeated cycles of CELL DEATH AND PROLIFERATION. MOST develops in patients with CIRRHOSIS, although cancer can OCCASIONALLY OCCUR WITHOUT cirrhosis.","s":14},{"t":"Helicobacter pylori — the one BACTERIUM","d":"GRAM-NEGATIVE, colonizes the stomach → CHRONIC GASTRITIS → may lead to ATROPHIC GASTRITIS and INTESTINAL METAPLASIA. Associated with GASTRIC ADENOCARCINOMA and MALT LYMPHOMA. ERADICATION can REDUCE gastric cancer risk and may INDUCE REGRESSION of some early MALT lymphomas.","s":14},{"t":"Radiation","d":"ULTRAVIOLET — UVB. And IONIZING radiation.","s":14},{"t":"Heredity — tumour suppressors","d":"Rb protein → RETINOBLASTOMA (rare childhood eye tumour) AND OSTEOSARCOMA. NF-1 and NF-2 → NEUROFIBROMATOSIS types 1 and 2, central and peripheral nervous system tumours. p16 (INK4a) → MALIGNANT MELANOMA. APC → FAMILIAL ADENOMATOSIS POLYPOSIS: 500–2500 premalignant adenomatous polyps in the TEENS AND TWENTIES, COLON CANCER BY AGE 50.","s":14},{"t":"Heredity — repair genes","d":"BRCA-1 and BRCA-2: a MINORITY of breast cancer patients have an inherited mutation. XERODERMA PIGMENTOSUM: inherited DEFECTIVE DNA REPAIR GENES, cannot repair mutations caused by UVB → increased skin cancer in SUN-EXPOSED areas.","s":14},{"t":"Three purposes of staging","d":"INDICATES EXTENT OF SPREAD within the patient · DETERMINES PROGNOSIS · GUIDES MANAGEMENT.","s":15},{"t":"Staging is based on three things","d":"SIZE OF PRIMARY LESION · EXTENT OF SPREAD TO REGIONAL LYMPH NODES · PRESENCE OR ABSENCE OF BLOOD-BORNE METASTASES. Which is exactly T, N and M.","s":15},{"t":"T — primary lesion","d":"Tis = lesion HAS NOT INVADED THROUGH THE TISSUE BASEMENT MEMBRANE (&#x27;is&#x27; = IN SITU). T1–T3 or higher = increasing SIZE and increasing DEPTH OF INVASION.","s":15},{"t":"N — regional lymph nodes","d":"Nx = nodes CANNOT BE ASSESSED. N0 = NO regional nodal metastasis. N1, N2 or higher = increasing NUMBER AND RANGE of nodes involved.","s":15},{"t":"M — metastasis","d":"Mx = distant metastasis CANNOT BE ASSESSED. M0 = NO distant metastasis. M1 = DISTANT METASTASIS.","s":15},{"t":"The convention, and the caveat","d":"x ALWAYS means cannot be assessed; 0 ALWAYS means none found. And: TNM DEFINITIONS ARE CANCER-SPECIFIC — for some cancers DEPTH OF INVASION IS MORE IMPORTANT THAN SIZE.","s":15},{"t":"HE SIGNPOSTS NOTHING","d":"84 minutes, two independent transcriptions, and NO statement about what is or is not on the exam. Nothing was flagged and nothing was excluded. Study the twelve objectives evenly.","s":16},{"t":"Metaplasia, his example","d":"CHRONIC GERD. The lower oesophagus is SQUAMOUS and cannot resist acid → metaplasia to COLUMNAR = BARRETT&#x27;S OESOPHAGUS → increased risk of oesophageal carcinoma. His corollary: in oesophageal carcinoma, SQUAMOUS cells on the sample = a PRIMARY cancer; COLUMNAR cells = SECONDARY TO REFLUX.","s":16},{"t":"Dysplasia, his example","d":"CERVICAL DYSPLASIA, usually caused by HPV — which ties straight back to E6/E7, p53 and RB in the carcinogenesis section. “Might be archival one day because of the vaccine.”","s":16},{"t":"Hypertrophy, his example","d":"WEIGHT TRAINING. Striated muscle cells DO NOT DIVIDE. Protein + resistance → more ACTIN AND MYOSIN → each FIBRE gets bigger → the organ gets bigger. BIGGER FIBRES, NOT MORE FIBRES — that is the whole distinction from hyperplasia.","s":16},{"t":"Why &#x27;permanent tissues&#x27; matters","d":"“THE MORE SPECIALIZED THE TISSUE IS, THE LESS IT CAN PROLIFERATE.” Skeletal muscle and NEURONS are the two he named. Which is why hypertrophy is the only growth response available to them.","s":16},{"t":"A LINK THE SLIDES DO NOT MAKE","d":"“As the degree of differentiation goes from well to anaplasia, THE TUMOUR BECOMES MORE AGGRESSIVE.” The deck gives grading as a scale of resemblance and stops. He attaches the prognosis. Also: ANAPLASIA = ATYPIA, and differentiation is always judged against THE PARENT CELL.","s":16},{"t":"Who diagnoses cancer","d":"THE PATHOLOGIST — “the only one that can diagnose cancer”. Said twice. Grading is a histological judgement made on tissue.","s":16},{"t":"How to PREDICT where mets go","d":"REASON FROM THE VESSELS. GI primary drains by the PORTAL VEIN → LIVER. LUNG cancer sits downstream of the pulmonary circulation, so its cells enter the LEFT HEART and go out the CAROTIDS → BRAIN. “Knowing the vasculature will tell you where there&#x27;s possibly mets forming.”","s":16},{"t":"His carcinoma in situ mnemonic","d":"“Carcinoma in SIGHT.” The cancerous cells are THERE, but have NOT broken through the BASEMENT MEMBRANE. Once they do, it is an INVASIVE carcinoma.","s":16},{"t":"Nomenclature down to the morphemes","d":"-OMA = tumour (plural CARCINOMATA, not carcinomas). ADENO- = glandular. LEIO- = smooth muscle (leiomyosarcoma). RHABDO- = skeletal muscle (rhabdomyosarcoma). Full nomenclature comes later in the course.","s":16},{"t":"Why epithelium sloughs","d":"EPITHELIAL TISSUE IS AVASCULAR, so the outermost layers are furthest from the nutrient supply and slough off. That is what a NORMAL epithelium looks like, before you compare it with a dysplastic one.","s":16},{"t":"He opened with “This is for the test”","d":"CATARACTS · MACULAR DEGENERATION · THE VISUAL PATHWAY · REFRACTION ERRORS · RETINAL DETACHMENT CAUSES · GLAUCOMA · PRESBYOPIA (added after he said “that’s it”).","s":17},{"t":"Glaucoma — what exactly he asked","d":"“What’s the PATHOPHYSIOLOGICAL EXPLANATION for vision loss there?” Answer: raised pressure compresses GANGLION CELL AXONS → APOPTOSIS → DISC CUPPING. It is NERVE loss, not media opacity.","s":17},{"t":"Visual pathway — SCOPED","d":"KNOW A, B, C: optic NERVE, optic CHIASM, optic TRACT. D (optic radiation) and E (occipital cortex) he DEFERRED TO NEUROLOGY — “you can know that if you want.” He also said “MEMORISE THIS: optic nerve, optic chiasm, optic tract.”","s":17},{"t":"Refraction errors — what he wants","d":"GLOBE GEOMETRY, not lens prescriptions. “Not that important, concave and convex for my purposes. MORE IMPORTANT is knowing the difference between MYOPIA, HYPEROPIA, and the GLOBE SHAPE.” He then contradicted himself on the lenses and corrected mid-sentence — trust the slide, expect the geometry.","s":17},{"t":"Retinal detachment — what he wants","d":"“The DIFFERENT THINGS that can cause retinal detachment.” Three mechanisms, not one presentation.","s":17},{"t":"Presbyopia — the one he came back for","d":"The lens is normally ELASTIC; with age it HARDENS, so it can no longer change shape → CANNOT ACCOMMODATE. Tied to the A in PERRLA (Pupils Equal, Round, Reactive to Light, ACCOMMODATION).","s":17},{"t":"The three tunics","d":"FIBROUS (outer): sclera + cornea. UVEA (vascular, middle): choroid + ciliary body + iris. RETINA (neurosensory, inner).","s":18},{"t":"Five unique features","d":"CORNEA AVASCULAR — oxygenated by AIR AND TEARS, ~70% OF REFRACTION. RETINA has the HIGHEST OXYGEN CONSUMPTION of any tissue, higher than cortex. Only place to see LIVE NEURAL TISSUE and NATIVE MICROCIRCULATION directly. ~83% of knowledge acquisition.","s":18},{"t":"Three requirements for vision","d":"IMAGE FORMATION (cornea + lens onto retina) · PHOTORECEPTOR EXCITATION (photons → HYPERPOLARISING potentials) · NEURAL TRANSMISSION (optic nerve → occipital cortex).","s":18},{"t":"Rods vs cones","d":"RODS ~120 MILLION — dim light, PERIPHERAL retina. CONES ~6 MILLION — colour + sharp acuity, concentrated in the FOVEA CENTRALIS within the macula.","s":18},{"t":"Retinal pigment epithelium — 3 jobs","d":"ABSORBS SCATTERED LIGHT · PHAGOCYTOSES outer photoreceptor segments · maintains the BLOOD-RETINAL BARRIER.","s":18},{"t":"Retinal interneurons","d":"BIPOLAR, HORIZONTAL, AMACRINE modulate the signal → GANGLION CELLS, whose axons form the OPTIC NERVE.","s":18},{"t":"Optic disc","d":"THE BLIND SPOT — no rods or cones.","s":18},{"t":"Aqueous: made where, drains where","d":"MADE by the NON-PIGMENTED EPITHELIUM OF THE CILIARY BODY into the POSTERIOR chamber → through the pupil → ANTERIOR chamber (nourishes avascular LENS and CORNEA) → TRABECULAR MESHWORK → CANAL OF SCHLEMM → EPISCLERAL VEINS. That route is all of glaucoma.","s":18},{"t":"Vitreous","d":"WATER + TYPE II COLLAGEN + HYALURONIC ACID. Shock absorber pressing retina onto RPE. Its age LIQUEFACTION is all of rhegmatogenous detachment.","s":18},{"t":"MYOPIA","d":"Axial globe TOO LONG → focal point IN FRONT of the retina. Near vision preserved.","s":19},{"t":"HYPEROPIA","d":"Axial globe TOO SHORT → focal point BEHIND the retina. Distance vision preserved.","s":19},{"t":"ASTIGMATISM","d":"IRREGULAR CORNEAL OR LENS CURVATURE → non-spherical focal points, so NOTHING focuses properly anywhere. Can STACK on myopia or hyperopia.","s":19},{"t":"PRESBYOPIA","d":"LENS SCLEROSIS, loss of elasticity + loss of ciliary accommodation → cannot focus NEAR. “Readers”/bifocals.","s":19},{"t":"STRABISMUS = MECHANICAL","d":"Visual axes fail to land on corresponding retinal points. ESOtropia in · EXOtropia out · HYPERtropia up · HYPOtropia down. From EOM IMBALANCE or CN III/IV/VI PALSY.","s":19},{"t":"AMBLYOPIA = VISUAL DEFICIT","d":"Reduced BEST-CORRECTED acuity from abnormal visual processing in the CRITICAL DEVELOPMENTAL PERIOD. Causes: uncorrected strabismus, severe refractive error, DEPRIVATION (congenital cataract, ptosis).","s":19},{"t":"Amblyopia treatment window","d":"BEFORE AGE 7–8 — because that is when the visual system stops being plastic.","s":19},{"t":"CATARACT — four mechanisms","d":"SENILE: insoluble aggregation of LENS CRYSTALLIN PROTEINS. DIABETES: glucose → SORBITOL → OSMOTIC SWELLING. DRUGS/TRAUMA: chronic CORTICOSTEROIDS, capsule rupture. CONGENITAL/ENVIRONMENTAL: DOWN SYNDROME, UV, oxidative damage.","s":20},{"t":"Cataract presentation","d":"GRADUAL, PAINLESS, BILATERAL blurring · GLARE AROUND HEADLIGHTS AT NIGHT · MONOCULAR DIPLOPIA · altered colour. EXAM: LOSS OF THE RED REFLEX, leukocoria if severe. Usually PERIPHERAL in the lens; NUCLEAR is often post-TRAUMATIC.","s":20},{"t":"GLAUCOMA — the hallmark (he asked for this)","d":"Raised IOP compresses RETINAL GANGLION CELL AXONS → GANGLION CELL APOPTOSIS → progressive OPTIC DISC CUPPING, cup-to-disc ratio &gt; 0.5.","s":20},{"t":"OPEN-ANGLE","d":"Angle stays OPEN; MICROSCOPIC RESISTANCE in the TRABECULAR MESHWORK impairs outflow → gradual rise. INSIDIOUS, PAINLESS, BILATERAL. PITFALL: ASYMPTOMATIC until severe PERIPHERAL loss (“tunnel vision”).","s":20},{"t":"ANGLE-CLOSURE","d":"MYDRIASIS displaces iris forward against cornea (IRIS BOMBÉ) → total outflow blockage → spike ABOVE 50 mmHg. SEVERE PAIN, HEADACHE, HALOS, CLOUDY CORNEA, FIXED MID-DILATED PUPIL, NAUSEA/VOMITING.","s":20},{"t":"The deck contradicts itself on normal IOP","d":"Slide 24 says 10–21 mmHg; slide 25 says “about 6–19.” PD2’s deck independently says 10–21. NOTHING IS GRADED ON THIS. What is NOT disputed: the acute spike ABOVE 50.","s":20},{"t":"Why age matters first","d":"The VITREOUS LIQUEFIES with age. Liquefied vitreous is what can pass through a break.","s":21},{"t":"RHEGMATOGENOUS","d":"FULL-THICKNESS TEAR → liquefied vitreous enters the SUBRETINAL SPACE and PEELS the retina off the RPE. Risks: PVD, AGE, SEVERE MYOPIA, TRAUMA, LATTICE DEGENERATION. Symptoms: PHOTOPSIA · SHOWER OF FLOATERS · CURTAIN FALLING.","s":21},{"t":"TRACTIONAL","d":"Proliferative FIBROVASCULAR MEMBRANES on the retinal surface PHYSICALLY PULL the retina off. Chiefly PROLIFERATIVE DIABETIC RETINOPATHY; also prior trauma/surgery/vitrectomy scarring.","s":21},{"t":"EXUDATIVE (SEROUS)","d":"Subretinal fluid with NO TEAR AND NO TRACTION — BLOOD-RETINAL BARRIER BREAKDOWN. Causes: SEVERE MALIGNANT HYPERTENSION, SARCOIDOSIS, CHOROIDAL MELANOMA.","s":21},{"t":"DRY (ATROPHIC) AMD","d":"Slow bilateral degeneration of photoreceptors, RPE and choroid. HALLMARK: DRUSEN — yellow extracellular debris (LIPOFUSCIN, APOLIPOPROTEINS) beneath the RPE and BRUCH MEMBRANE. Slow central loss, METAMORPHOPSIA, SCOTOMA.","s":21},{"t":"WET (NEOVASCULAR) AMD","d":"HYPOXIA + INFLAMMATION → CHOROIDAL NEOVASCULARISATION beneath the RPE into the subretinal space. Leak → RAPID central loss, DISCIFORM SCARRING, detachment. ~90% OF SEVERE AMD BLINDNESS.","s":21},{"t":"Pathogenesis of AMD","d":"UNKNOWN — the deck says so for both forms.","s":21},{"t":"Two blindness statistics — do not swap them","d":"DIABETIC RETINOPATHY: leading cause of new-onset blindness in US adults 20–74. MACULAR DEGENERATION: leading cause in US adults OVER 75.","s":21},{"t":"Diabetic retinopathy cascade","d":"CHRONIC HYPERGLYCAEMIA damages capillaries + endothelial basement membranes → OCCLUSION + HYPOXIA. NON-PROLIFERATIVE: dilated veins, MICROANEURYSMS, dot/blot haemorrhages, HARD EXUDATES (lipid, OUTER PLEXIFORM layer), COTTON-WOOL SPOTS (NERVE FIBRE layer ischaemia), macular oedema. PROLIFERATIVE: ischaemia → VEGF → NEOVASCULARISATION → vitreous haemorrhage, traction, detachment.","s":21},{"t":"THE ONE FACT EVERYTHING FOLLOWS FROM","d":"NASAL retinal fibres — which carry the TEMPORAL visual fields — CROSS at the chiasm. TEMPORAL retinal fibres stay IPSILATERAL.","s":22},{"t":"The pathway","d":"OPTIC DISC → OPTIC NERVE → CHIASM → OPTIC TRACT → LATERAL GENICULATE NUCLEUS → OPTIC RADIATION → OCCIPITAL CORTEX.","s":22},{"t":"A — ipsilateral OPTIC NERVE","d":"MONOCULAR BLINDNESS. Causes: trauma, optic neuritis, ischaemic optic neuropathy.","s":22},{"t":"B — OPTIC CHIASM (centre)","d":"BITEMPORAL HEMIANOPSIA — only the crossing NASAL fibres are cut, and they carry the TEMPORAL fields. Commonest cause: PITUITARY ADENOMA.","s":22},{"t":"C — OPTIC TRACT / LGN","d":"CONTRALATERAL HOMONYMOUS HEMIANOPSIA. Stroke, tumour, demyelination.","s":22},{"t":"D and E — HE DEFERRED THESE","d":"D temporal optic radiation → contralateral SUPERIOR quadrantanopsia (“pie in the sky”). E occipital cortex, PCA occlusion → contralateral homonymous hemianopsia WITH MACULAR SPARING (dual supply). “You can know that if you want.”","s":22},{"t":"Losing one eye","d":"Loses the BINOCULAR OVERLAP and therefore DEPTH PERCEPTION. Everything becomes flat.","s":22}],"map":{"clinical-pathophysiology-i-exam-1-abnormal-cell-growth-quiz-version-2":[90,114,91,93,109,114,123,91,108,115,84,125,101,105,104,96,86,107,112,91,106,101,106,99,128,110,131,105,119,123],"clinical-pathophysiology-i-exam-1-abnormal-cell-growth-quiz":[93,115,124,90,93,99,112,94,83,102,95,114,82,121,116,113,101,95,131,112,107,98,115,-1,-1,105,102,88,95,129],"clinical-pathophysiology-i-exam-1-dermatology-pathophys-quiz-version-2":[-1,69,79,71,-1,59,10,59,78,63,79,-1,70,68,-1,57,74,50,77,77,-1,79,75,79,60,53,48,-1,52,60],"clinical-pathophysiology-i-exam-1-dermatology-pathophys-quiz":[46,-1,66,65,79,63,54,70,68,57,48,118,-1,75,72,66,118,61,-1,58,49,71,67,51,-1,64,51,73,76,71],"clinical-pathophysiology-i-exam-1-inflammation-quiz-version-2":[22,23,24,24,6,10,44,29,31,9,-1,-1,6,31,37,40,2,27,39,35,39,13,29,23,-1,34,11,28,18,8],"clinical-pathophysiology-i-exam-1-inflammation-quiz":[4,28,31,33,-1,14,35,38,22,7,17,-1,-1,19,15,1,-1,24,1,-1,1,32,37,26,44,22,38,3,20,-1],"clinical-pathophysiology-i-exam-1-ophthalmic-pathophys-quiz-version-2":[-1,141,139,150,137,-1,144,-1,159,168,-1,148,-1,-1,151,69,169,165,175,159,-1,142,155,150,-1,152,155,-1,165,151],"clinical-pathophysiology-i-exam-1-ophthalmic-pathophys-quiz":[137,-1,-1,153,166,137,157,172,-1,-1,158,139,-1,172,-1,-1,176,148,165,174,141,155,149,167,140,170,142,138,162,168]}};
